#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
source "$SCRIPT_DIR/_common.sh"
require_commands curl jq openssl docker
BASE_URL="${1:-http://localhost:18081}"
temp_dir="$(new_temp_dir)"; session_counter=0
names=(PAYMENT_CANCELLATION_CRASH_LAB_ENABLED PAYMENT_CANCELLATION_CRASH_LAB_ORDER_ID PAYMENT_CANCELLATION_CRASH_LAB_PHASE PAYMENT_CANCELLATION_CRASH_LAB_PAUSE)
declare -A saved present
for name in "${names[@]}";do if [[ -v $name ]];then present[$name]=1;saved[$name]="${!name}";else present[$name]=0;fi;done

wait_healthy(){ for _ in $(seq 1 45);do curl -fsS "$BASE_URL/actuator/health"|jq -e '.status=="UP"'>/dev/null 2>&1&&return;sleep 1;done;echo 'Backend did not become healthy'>&2;return 1; }
restart_backend(){ export PAYMENT_CANCELLATION_CRASH_LAB_ORDER_ID="${1:-1}" PAYMENT_CANCELLATION_CRASH_LAB_PHASE="${2:-AFTER_CANCELLATION_BEGIN}" PAYMENT_CANCELLATION_CRASH_LAB_ENABLED="${3:-false}" PAYMENT_CANCELLATION_CRASH_LAB_PAUSE=5m;compose up -d --no-deps --force-recreate commerce-service >/dev/null;wait_healthy; }
restore(){ rm -rf -- "$temp_dir";for name in "${names[@]}";do if [[ "${present[$name]}" == 1 ]];then export "$name=${saved[$name]}";else unset "$name";fi;done;compose up -d --no-deps --force-recreate commerce-service >/dev/null;wait_healthy||true; }
trap restore EXIT
sql(){ compose exec -T commerce-db mysql -ucommerceflow -pcommerceflow-password -Nse "$1" commerceflow 2>/dev/null|tr -d '\r'; }
payment_sql(){ compose exec -T payment-simulator-db commerce-db -upayment -ppayment-password -Nse "$1" payment_platform 2>/dev/null|tr -d '\r'; }
new_customer(){ session_counter=$((session_counter+1));CUSTOMER_JAR="$temp_dir/customer-$session_counter.cookies";IFS=$'\t' read -r CUSTOMER_HEADER CUSTOMER_TOKEN<<<"$(storefront_login "$BASE_URL" demo@example.com "$CUSTOMER_JAR")";if ! json_request GET "$BASE_URL/api/addresses/selected" "$CUSTOMER_JAR">/dev/null 2>&1;then address="$(json_request POST "$BASE_URL/api/addresses" "$CUSTOMER_JAR" "$CUSTOMER_HEADER" "$CUSTOMER_TOKEN" '{"recipientName":"Crash Lab","phone":"13800000000","countryCode":"CN","stateProvince":"Shanghai","city":"Shanghai","district":"Pudong","addressLine1":"2 Recovery Road","addressLine2":"","postalCode":"200120","label":"Crash Lab","isDefault":true}')";json_request PUT "$BASE_URL/api/addresses/$(jq -r .id<<<"$address")/select" "$CUSTOMER_JAR" "$CUSTOMER_HEADER" "$CUSTOMER_TOKEN" '{}' >/dev/null;fi; }
new_fixture(){ new_customer;json_request POST "$BASE_URL/api/cart/items" "$CUSTOMER_JAR" "$CUSTOMER_HEADER" "$CUSTOMER_TOKEN" '{"productId":1,"quantity":1,"note":"crash-recovery-lab"}'>/dev/null;order="$(json_request POST "$BASE_URL/api/purchase-orders/checkout" "$CUSTOMER_JAR" "$CUSTOMER_HEADER" "$CUSTOMER_TOKEN" '{}')";payment="$(json_request POST "$BASE_URL/api/purchase-orders/$(jq -r .id<<<"$order")/payments" "$CUSTOMER_JAR" "$CUSTOMER_HEADER" "$CUSTOMER_TOKEN" "$(jq -nc --arg key "$(uuid_hex)" '{idempotencyKey:$key,simulateFailure:false,channel:"ALIPAY"}')")";jq -nc --argjson id "$(jq -r .id<<<"$order")" --arg tx "$(jq -r .payment.channelTransactionNo<<<"$payment")" --argjson amount "$(jq -r .payment.amount<<<"$payment")" '{id:$id,tx:$tx,amount:$amount}'; }
start_cancel(){ local id="$1";local jar="$temp_dir/cancel-$id.cookies";IFS=$'\t' read -r header token<<<"$(storefront_login "$BASE_URL" demo@example.com "$jar")";(curl -sS -X POST -b "$jar" -H "$header: $token" -H 'Content-Type: application/json' --data '{"reason":"process crash recovery lab"}' "$BASE_URL/api/purchase-orders/$id/cancel">/dev/null 2>&1||true)&CANCEL_PID=$!; }
wait_pause(){ local id="$1" phase="$2";for _ in $(seq 1 30);do compose logs --no-color commerce-service 2>/dev/null|grep -q "PAYMENT_CANCELLATION_CRASH_LAB_PAUSED orderId=$id phase=$phase"&&return;sleep 1;done;echo "Crash hook not reached: order=$id phase=$phase" >&2;return 1; }
kill_backend(){ compose kill -s SIGKILL commerce-service >/dev/null;wait "${1:-$CANCEL_PID}" 2>/dev/null||true; }
retry_cancel(){ local id="$1";new_customer;json_request POST "$BASE_URL/api/purchase-orders/$id/cancel" "$CUSTOMER_JAR" "$CUSTOMER_HEADER" "$CUSTOMER_TOKEN" '{"reason":"process crash recovery lab retry"}'; }
make_notice(){ local fixture="$1" prefix="$2";NOTICE="$(jq -nc --arg id "$prefix-$(uuid_hex)" --arg tx "$(jq -r .tx<<<"$fixture")" --argjson amount "$(jq -r .amount<<<"$fixture")" '{notificationId:$id,channelTransactionNo:$tx,channel:"ALIPAY",status:"SUCCESS",amount:$amount,currency:"CNY",failureReason:""}')";SIGNATURE="$(printf '%s' "$NOTICE"|openssl dgst -sha256 -hmac demo-platform-callback-secret -binary|openssl base64 -A)"; }

restart_backend
merchant_jar="$temp_dir/merchant.cookies";IFS=$'\t' read -r merchant_header merchant_token<<<"$(storefront_login "$BASE_URL" merchant@example.com "$merchant_jar")";available="$(json_request GET "$BASE_URL/api/merchant/inventory" "$merchant_jar"|jq -r '.[]|select(.productId==1)|.stockAvailable')";if((available<20));then json_request POST "$BASE_URL/api/merchant/inventory/1/adjustments" "$merchant_jar" "$merchant_header" "$merchant_token" "$(jq -nc --argjson delta "$((20-available))" '{delta:$delta,reason:"Prepare crash recovery lab inventory"}')">/dev/null;fi

begin="$(new_fixture)";begin_id="$(jq -r .id<<<"$begin")";restart_backend "$begin_id" AFTER_CANCELLATION_BEGIN true;start_cancel "$begin_id";wait_pause "$begin_id" AFTER_CANCELLATION_BEGIN;kill_backend;[[ "$(sql "SELECT CONCAT(o.status,':',p.status) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$begin_id")" == CANCELLING:PENDING ]]||{ echo 'Invalid after-begin middle state'>&2;exit 1;};restart_backend;[[ "$(retry_cancel "$begin_id"|jq -r .status)" == CANCELLED ]]||{ echo 'CANCELLING retry failed'>&2;exit 1;}

closed="$(new_fixture)";closed_id="$(jq -r .id<<<"$closed")";closed_tx="$(jq -r .tx<<<"$closed")";restart_backend "$closed_id" AFTER_CHANNEL_CLOSE true;start_cancel "$closed_id";wait_pause "$closed_id" AFTER_CHANNEL_CLOSE;kill_backend;[[ "$(sql "SELECT CONCAT(o.status,':',p.status) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$closed_id")" == CANCELLING:PENDING ]]||exit 1;[[ "$(payment_sql "SELECT status FROM channel_transaction WHERE channel_transaction_no='$closed_tx'")" == CLOSED ]]||{ echo 'Channel close not committed'>&2;exit 1;};restart_backend;[[ "$(retry_cancel "$closed_id"|jq -r .status)" == CANCELLED ]]||exit 1;[[ "$(sql "SELECT CONCAT(status,':',(SELECT COUNT(*) FROM order_events WHERE order_id=$closed_id AND event_type='ORDER_CANCELLED')) FROM payment_records WHERE order_id=$closed_id")" == CLOSED:1 ]]||{ echo 'Post-close retry audit failed'>&2;exit 1;}

payment_crash="$(new_fixture)";payment_id="$(jq -r .id<<<"$payment_crash")";make_notice "$payment_crash" CRASH;restart_backend "$payment_id" AFTER_PAYMENT_RECORD true;(curl -sS -H "X-Callback-Signature: $SIGNATURE" -H 'Content-Type: application/json' --data "$NOTICE" "$BASE_URL/api/payment-notifications/callback">/dev/null 2>&1||true)&callback_pid=$!;wait_pause "$payment_id" AFTER_PAYMENT_RECORD;kill_backend "$callback_pid";[[ "$(sql "SELECT CONCAT(o.status,':',p.status,':',(SELECT COUNT(*) FROM payment_notifications WHERE payment_id=p.id),':',(SELECT COUNT(*) FROM payment_events WHERE payment_id=p.id AND event_type='CALLBACK_SUCCESS')) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$payment_id")" == PENDING_PAYMENT:PENDING:0:0 ]]||{ echo 'Callback transaction did not roll back'>&2;exit 1;};restart_backend;[[ "$(curl -fsS -H "X-Callback-Signature: $SIGNATURE" -H 'Content-Type: application/json' --data "$NOTICE" "$BASE_URL/api/payment-notifications/callback"|jq -r .result)" == PROCESSED ]]||exit 1;[[ "$(sql "SELECT CONCAT(o.status,':',p.status,':',(SELECT COUNT(*) FROM payment_notifications WHERE payment_id=p.id),':',(SELECT COUNT(*) FROM payment_events WHERE payment_id=p.id AND event_type='CALLBACK_SUCCESS')) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$payment_id")" == PAID:SUCCESS:1:1 ]]||exit 1

late="$(new_fixture)";late_id="$(jq -r .id<<<"$late")";restart_backend "$late_id" AFTER_CANCELLATION_BEGIN true;start_cancel "$late_id";wait_pause "$late_id" AFTER_CANCELLATION_BEGIN;kill_backend;restart_backend;make_notice "$late" LATE;[[ "$(curl -fsS -H "X-Callback-Signature: $SIGNATURE" -H 'Content-Type: application/json' --data "$NOTICE" "$BASE_URL/api/payment-notifications/callback"|jq -r .result)" == PROCESSED ]]||exit 1;[[ "$(sql "SELECT CONCAT(o.status,':',p.status,':',(SELECT COUNT(*) FROM order_events WHERE order_id=o.id AND event_type='CANCELLATION_LOST_PAYMENT_RACE')) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$late_id")" == PAID:SUCCESS:1 ]]||{ echo 'Late callback recovery failed'>&2;exit 1;}
echo 'Payment/cancellation crash recovery passed: begin, committed channel close, callback rollback and late callback windows.'
